const PF_REAL_TROPHY_BR='data:image/jpeg;base64,';
'use strict';
function limitSavedRecords(){for(const [key,max]of [['campaigns',10],['careers',5]]){const ids=Object.keys(store[key]);for(const id of ids.slice(0,Math.max(0,ids.length-max)))delete store[key][id]}store.quickHistory=store.quickHistory.slice(-5)}
function bindDeleteSaves(){for(const [selector,key]of [['data-delete-campaign','campaigns'],['data-delete-career','careers']])document.querySelectorAll('['+selector+']').forEach(b=>b.onclick=()=>{const id=b.getAttribute(selector),record=store[key][id];if(!record)return;const d=$('deleteSaveDialog');$('deleteSaveName').textContent=key==='careers'?record.profile.name:record.team+' · '+record.comp.name;$('deleteSaveConfirm').onclick=()=>{delete store[key][id];if(key==='campaigns'&&season&&keyForDelete(season)===id)season=null;persist();d.close();renderSaves();toast('Progresso apagado.')} ;d.showModal()})}
function keyForDelete(s){return s.comp.id+'::'+s.team}
function groupDrawButtons(s,idx,html){if(idx!==0||!s.comp.groups||!['lib','world','groups','history'].includes(s.comp.kind))return html;const played=s.stages.some(st=>st.rounds.flat().some(m=>m.hg!=null));return html.replace('</div>','<button id="randomGroups" '+(played?'disabled':'')+'>Randomizar</button><button id="restoreGroups" '+(played?'disabled':'')+'>Restaurar</button></div>')+'<p class="fine">Sorteio livre antes da primeira partida. Restaurar recupera os grupos da edição; não segue potes ou restrições de federação.</p>'}
function bindGroupDraw(){for(const [id,restore]of [['randomGroups',false],['restoreGroups',true]])if($(id))$(id).onclick=()=>{try{E.regroup(season,restore);save();renderCompetition();toast(restore?'Grupos originais restaurados.':'Grupos sorteados.')}catch(e){toast(e.message)}}}
async function toggleMatchFullscreen(){try{if(!player)return;const api=player.ruffle();if(api.isFullscreen||document.fullscreenElement){if(api.exitFullscreen)api.exitFullscreen();else await document.exitFullscreen();}else if(api.enterFullscreen)api.enterFullscreen();else if(player.requestFullscreen)await player.requestFullscreen();else toast('Tela cheia indisponível neste navegador.');}catch{toast('Permita tela cheia no navegador e tente novamente.')}}
function trophyRoomHtml(c){const catalogue=window.ME_TROPHIES||{},byName={'Brasileirão · Série A':'br0','Premier League':'eng','Bundesliga':'ger','Champions League':'ucl','Champions League · Carreira':'ucl','Libertadores':'lib','Libertadores · Carreira':'lib','Copa do Mundo':'world','Liga Conferência da UEFA':'uecl','Liga Conferência da UEFA · Carreira':'uecl'};return `<section class="panel"><span class="tag">SALA DE TROFÉUS</span><h2>Conquistas da sua carreira</h2><div class="trophy-grid">${c.titles.map(t=>{const photo=catalogue[t.compId]||catalogue[byName[t.competition]];return `<article class="trophy-card"><img loading="lazy" src="${esc(photo?.image||embeddedLogo('trophy.svg'))}" alt="${esc(photo?'Fotografia: '+photo.label:'Troféu ilustrativo · fotografia não confirmada')}"><h3>${esc(t.competition)}</h3><b class="fixture-team">${teamLogo(t.club,true)}${esc(t.club)}</b><span class="tag">${esc(t.year)}</span>${photo?`<small class="fine">${esc(photo.label)}<br><a href="${esc(photo.source)}" target="_blank" rel="noopener noreferrer">${esc(photo.author)}</a> · <a href="${esc(photo.licenseUrl)}" target="_blank" rel="noopener noreferrer">${esc(photo.license)}</a></small>`:'<small class="fine">Taça ilustrativa · fotografia não confirmada</small>'}</article>`}).join('')||'<p class="muted">Vença uma competição nesta carreira para inaugurar sua coleção.</p>'}</div><p class="fine">Somente títulos conquistados nesta carreira. As fotografias mostram o troféu identificado na legenda; competições adaptadas e taças sem foto documentada usam uma ilustração.</p></section>`}
let calendarScope='club',calendarCompetition='all',calendarMonth='all';
function careerSchedule(c){const rows=[];for(const s of c.world){const team=C.userTeam(c,s);if(!team)continue;let n=0;for(let si=s.at;si<s.stages.length;si++){const st=s.stages[si];for(let r=st.cursor;r<st.rounds.length;r++){for(const m of st.rounds[r])if(m.hg==null&&!m.skipped&&(m.h===team||m.a===team)){const tick=s.meta.start+(s.meta.done+n)*s.meta.interval,day=Math.min(364,Math.round(tick*4.7)),date=new Date(Date.UTC(c.year,0,1+day));rows.push({id:s.comp.id,name:s.comp.name,scope:s.meta.category==='nation'?'nation':'club',date:date.toISOString().slice(0,10),h:m.h,a:m.a,phase:st.label,conditional:false})}n++}}if(!s.finished&&s.stages[s.at].after!=='done'&&s.stages[s.at].after!=='league')rows.push({id:s.comp.id,name:s.comp.name,scope:s.meta.category==='nation'?'nation':'club',date:'',phase:'Próximas fases condicionadas à classificação',conditional:true})}return rows.sort((a,b)=>(a.date||'9999').localeCompare(b.date||'9999')||a.name.localeCompare(b.name))}
function calendarHtml(c){const rows=careerSchedule(c),pool=rows.filter(r=>r.scope===calendarScope),comps=[...new Map(pool.map(r=>[r.id,r.name]))];if(!comps.some(([id])=>id===calendarCompetition))calendarCompetition='all';const filtered=pool.filter(r=>(calendarCompetition==='all'||r.id===calendarCompetition)&&(calendarMonth==='all'||r.date.slice(5,7)===calendarMonth));return `<section class="panel career-calendar"><div class="career-tabs"><button data-calendar-scope="club" class="${calendarScope==='club'?'active':''}">Clube · ${esc(c.club)}</button><button data-calendar-scope="nation" class="${calendarScope==='nation'?'active':''}">Seleção ${c.national?'· '+esc(c.national):'· cargo indisponível'}</button></div><div class="form-grid"><label>Competição<select id="calendarCompetition"><option value="all">Todas</option>${comps.map(([id,name])=>`<option value="${esc(id)}" ${id===calendarCompetition?'selected':''}>${esc(name)}</option>`).join('')}</select></label><label>Mês<select id="calendarMonth"><option value="all">Todo o ano</option>${Array.from({length:12},(_,i)=>`<option value="${String(i+1).padStart(2,'0')}" ${Number(calendarMonth)===i+1?'selected':''}>${new Date(Date.UTC(c.year,i)).toLocaleDateString('pt-BR',{month:'long',timeZone:'UTC'})}</option>`).join('')}</select></label></div><div class="schedule-list">${filtered.map(r=>r.conditional?`<article><small>${esc(r.name)}</small><b>A definir</b><span>${esc(r.phase)}</span></article>`:`<article><time datetime="${r.date}">${new Date(r.date+'T12:00:00Z').toLocaleDateString('pt-BR',{timeZone:'UTC'})}</time><b class="table-team">${teamLogo(r.h,true)}${esc(r.h)} × ${teamLogo(r.a,true)}${esc(r.a)}</b><span>${esc(r.name)} · ${esc(r.phase)}</span></article>`).join('')||`<p class="muted">${calendarScope==='nation'&&!c.national?'Conquiste a Copa Intercontinental no ciclo de quatro anos para receber o convite da seleção.':'Nenhum jogo definido neste filtro. Novas fases e competições aparecem conforme o calendário avança.'}</p>`}</div><p class="fine">Datas geradas pelo jogo, com ligas e copas intercaladas. Adversários de fases futuras dependem de classificação e sorteio; não são confrontos oficiais.</p></section>`}
function bindCalendar(c){document.querySelectorAll('[data-calendar-scope]').forEach(b=>b.onclick=()=>{calendarScope=b.dataset.calendarScope;calendarCompetition='all';calendarMonth='all';renderCareer(c)});for(const id of ['calendarCompetition','calendarMonth'])if($(id))$(id).onchange=()=>{if(id==='calendarCompetition')calendarCompetition=$(id).value;else calendarMonth=$(id).value;renderCareer(c)}}
function confirmCareerYear(c,action){if(c.history.some(h=>h.year<c.year-8)){$('historyWarningYear').textContent=String(c.year-9);$('historyWarningConfirm').onclick=()=>{$('historyWarning').close();action()};$('historyWarning').showModal()}else action()}
function qualificationZone(s,i,total){if(!s)return{cls:'',label:''};const c=s.comp,st=s.stages.findLast(x=>x.groups),multi=(st?.groups?.length||0)>1;if(multi)return i<(c.groupQualify||c.qualify||2)?{cls:'zone-blue',label:'Zona de classificação à próxima fase'}:{cls:'',label:''};const down=c.relegateCount||0;if(down&&i>=total-down)return{cls:'zone-red',label:'Zona de rebaixamento'};if(c.tier>1){if(i<(c.promoteDirect??c.promoteCount??0))return{cls:'zone-blue',label:'Zona de acesso'};if(c.kind==='promotion'&&i<(c.promoteDirect||2)+(c.playoffCount||4))return{cls:'zone-orange',label:'Playoffs de acesso'};return{cls:'',label:''}}if(c.id==='br0'){if(i<4)return{cls:'zone-blue',label:'Projeção: Libertadores'};if(i===4)return{cls:'zone-orange',label:'Projeção: preliminar da Libertadores'};if(i<11)return{cls:'zone-green',label:'Projeção: Sul-Americana'}}if(['Inglaterra','Espanha','Itália','Alemanha','França','Portugal'].includes(c.country)){if(i<4)return{cls:'zone-blue',label:'Projeção: competição continental principal'};if(i<6)return{cls:'zone-green',label:'Projeção: competição continental secundária'}}return{cls:'',label:''}}
function qualificationLegend(s){return '<div class="zone-legend"><span class="zone-blue">Classificação / acesso</span><span class="zone-orange">Preliminar / playoff</span><span class="zone-green">Continental secundária</span><span class="zone-red">Rebaixamento</span></div><p class="fine">Zonas indicativas das regras adaptadas da carreira. A tabela ainda pode mudar; licenças, reservas, campeões de copas e duplicação de vagas não são reproduzidos integralmente.</p>'}
